// Ne garde que la preuve : rien de la ligne lue ne descend dans le workflow.
// Stricte (032-019, M12) : exactement UNE ligne, aux colonnes exactes de regles_automatisation (0050_pilotage.sql:47-52). Une page HTML,
// une liste vide, un texte, une erreur ou une autre table arrêtent le passage (et la branche d'erreur le dit).
const COLONNES = 'actif,artisan_id,maillons,maj_le,prereglage';
const rendus = $input.all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
if (rendus.length !== 1) {
  throw new Error('Lecture de connexion : une ligne de regles_automatisation attendue, ' + rendus.length + ' rendue(s) (hôte de l identifiant Supabase mal réglé ?)');
}
const r = rendus[0];
const forme = Object.keys(r).sort().join(',') === COLONNES && typeof r.artisan_id === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(r.artisan_id)
  && typeof r.actif === 'boolean' && typeof r.prereglage === 'string' && r.maillons !== null && typeof r.maillons === 'object';
if (!forme) {
  throw new Error('Lecture de connexion : la réponse n est pas une ligne de regles_automatisation (hôte de l identifiant Supabase mal réglé ?)');
}
return [{ json: { connexion: 'ok', lignes: 1 } }];

// Le jour de Paris, le mode et les seuils (sources : plans/011-cadrage-01-11/briefs/c4-n8n-detecteurs.md).
const jour = $now.setZone('Europe/Paris').toISODate();
return [{ json: {
  jour,
  mode: 'simulation',
  seuils: {
    impayes_jours: [3, 10, 21],
    impayes_rattrapage: 10,
    impayes_ecart_min: 2,
    devis_jours: [3, 7, 14],
    devis_validite_defaut: 90,
    devis_expire_avant_jours: 7,
    demande_jours: [1, 3],
    demande_borne_jours: 10,
    avis_delai: 2,
    avis_rattrapage: 14
  }
} }];

// COPIE FIGÉE de lib/plans.ts (STUDIO, SIGNATURE, ENTREPRISE) et de lib/pilote/regles.ts (OUTILS_JAMAIS_AUTO,
// OUTILS_EXECUTABLES_PILOTE, OUTIL_TYPE). scripts/detecteurs-n8n-qa.mjs rougit si elle s'écarte du code.
const STUDIO = ['devis.ia', 'devis.prix_artisan', 'factures', 'factures.electronique',
  'plateforme.conversation', 'plateforme.comptes_clients', 'plateforme.gestion', 'plateforme.domaine_perso', 'site.domaine_perso',
  'canaux.email', 'relances', 'plateforme.personnalisation_avancee', 'chiffres', 'factures.relances', 'inventaire.stock',
  'inventaire.recherche_ia', 'canaux.whatsapp', 'export', 'assistant'];
const SIGNATURE = STUDIO.concat(['plateforme.ia.auto', 'relances.auto', 'factures.relances.auto', 'plateforme.ia.expert',
  'plateforme.regles', 'chiffres.auto', 'canaux.reseaux', 'support.prioritaire', 'crm', 'assistant.pilote']);
const ENTREPRISE = SIGNATURE.concat(['organisation.membres']);
return [{ json: {
  capacites: { studio: STUDIO, signature: SIGNATURE, entreprise: ENTREPRISE },
  outils_jamais_auto: ['marquer_facture_payee', 'creer_facture', 'creer_facture_libre', 'rembourser', 'payer', 'creer_avoir',
    'supprimer_devis_brouillon', 'supprimer_tarif', 'supprimer_article', 'augmenter_tarifs'],
  outils_executables_pilote: ['valider_reponse_proposee', 'relancer_devis', 'relancer_facture', 'envoyer_devis', 'envoyer_facture', 'repondre_client'],
  outil_type: { valider_reponse_proposee: 'reponse_prospect', relancer_devis: 'relance_devis', relancer_facture: 'relance_impaye', envoyer_devis: 'envoi_devis',
    envoyer_facture: 'envoi_facture', repondre_client: 'assistant_client', relancer_commande: 'assistant_client', demander_avis: 'assistant_client',
    envoyer_rappel_entretien: 'assistant_client' }
} }];

const ctx = $('Contexte du passage').first().json;
const offres = $('Capacités des offres').first().json;
const S = ctx.seuils;
const JOUR = ctx.jour;
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);
const jourParis = (v) => {
  if (typeof v !== 'string' || v.length < 10) return null;
  if (v.length === 10) return v;
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) return null;
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d)) p[x.type] = x.value;
  return p.year + '-' + p.month + '-' + p.day;
};
const ecart = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const centimes = (v) => { const n = Number(v); return Number.isFinite(n) ? Math.round(n * 100) : 0; };
// M2 (032-010) : toute jointure entre deux lectures passe par le compte ET l'identifiant, jamais par l'identifiant seul.
const paire = (artisanId, id) => artisanId + '|' + id;
const comptes = new Map(lignes('Lire comptes').map((a) => [a.id, a]));
const caps = (artisanId) => { const c = comptes.get(artisanId); return c && offres.capacites[c.plan] ? offres.capacites[c.plan] : null; };
const aLaCapacite = (artisanId, cap) => { const l = caps(artisanId); return !!l && l.includes(cap); };
const avant = $input.first().json.constats || [];
const nouveaux = [];
// `argent` : la pièce dont l'argent dort (facture ou devis), pour un total qui ne compte jamais deux fois la même (M5).
const constat = (numero, detecteur, artisanId, typeObjet, idObjet, etape, montant, jours, argent) => {
  nouveaux.push({ numero, detecteur, cle: detecteur + ':' + idObjet + ':' + etape, artisan_id: artisanId, objet: { type: typeObjet, id: idObjet }, etape, montant_centimes: montant, jours, argent: argent || null });
};
// n° 1 — facture échue à J+3, J+10, J+21 (règle decider, lib/relancesImpayes.ts:211-251), écart minimal de 2 jours (ECART_MIN, :33 ; M6).
const reglages = new Map(lignes('Lire reglages des relances').map((r) => [r.artisan_id, r]));
const arretees = new Set(lignes('Lire arrets de relance').filter((a) => !a.reprise_le).map((a) => paire(a.artisan_id, a.facture_id)));
const journal = lignes('Lire relances impayes');
for (const f of lignes('Lire factures')) {
  if (!aLaCapacite(f.artisan_id, 'factures.relances')) continue;
  if (f.statut !== 'emise' || f.payee_le || f.avoir_de) continue;
  const montant = centimes(f.total_ttc);
  if (montant <= 0) continue;
  const echeance = jourParis(f.date_echeance);
  if (!echeance || arretees.has(paire(f.artisan_id, f.id))) continue;
  const retard = ecart(JOUR, echeance);
  if (retard <= 0) continue;
  const siennes = journal.filter((e) => e.facture_id === f.id && e.artisan_id === f.artisan_id);
  if (siennes.some((e) => e.statut === 'a_valider')) continue;
  const pris = new Set(siennes.map((e) => Number(e.rang)));
  const r = reglages.get(f.artisan_id);
  const jours = r && Array.isArray(r.jours) && r.jours.length ? r.jours.map(Number) : S.impayes_jours;
  const libres = jours.map((j, i) => ({ rang: i + 1, jour: j })).filter((x) => !pris.has(x.rang));
  const choisie = libres.find((x) => retard >= x.jour && retard <= x.jour + S.impayes_rattrapage);
  if (!choisie) continue;
  const dernier = siennes.map((e) => jourParis(e.jour)).filter(Boolean).sort().pop();
  if (dernier && ecart(JOUR, dernier) < S.impayes_ecart_min) continue;
  constat(1, 'facture_echue', f.artisan_id, 'facture', f.id, 'j' + choisie.jour, montant, retard, { type: 'facture', id: f.id });
}
return [{ json: { constats: avant.concat(nouveaux) } }];

